SELECT r.PIPELINE_ID AS pipeline_id,r.PIPELINE_RUN_ID AS run_id,p.PIPELINE_CODE AS pipeline_code,p.PROJECT_ID AS project_id,r.STATUS AS status,(SELECT MAX(t.ERROR_MESSAGE) FROM AUD_TASK_RUN_LOG t WHERE t.PIPELINE_RUN_ID=r.PIPELINE_RUN_ID) AS error_message,r.RUN_LABEL AS run_label,r.RUN_DATE AS run_date FROM AUD_PIPELINES_RUN_LOG r JOIN CFG_PIPELINES p ON p.PIPELINE_ID=r.PIPELINE_ID WHERE r.PIPELINE_RUN_ID=:source_run_id
